import { test, expect as baseExpect } from "@playwright/test";
import { mkdir, mkdtemp, readFile, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { configuration, createService, startServer } from "../../server.mjs";

const expect = baseExpect.configure({ timeout: 120000 });
let service, server, workspace, run;
test.beforeAll(async () => {
  if (!process.env.NIXTLA_E2E_OUTPUT) throw new Error("Set NIXTLA_E2E_OUTPUT to a session artifact directory.");
  await mkdir(process.env.NIXTLA_E2E_OUTPUT, { recursive: true });
  workspace = await mkdtemp(join(resolve(process.env.NIXTLA_E2E_OUTPUT), "judgment-"));
  const input = join(workspace, "synthetic-run");
  await mkdir(join(input, "appendix"), { recursive: true });
  await writeFile(join(input, "manifest.json"), JSON.stringify({ spec: { horizon: 2, freq: "MS", unit_label: "minutes" } }));
  await writeFile(join(input, "forecast.csv"), "unique_id,ds,yhat,model\n001,2026-10-01,100,Conservative\n001,2026-11-01,120,Conservative\n");
  await writeFile(join(input, "appendix", "history.csv"), "unique_id,ds,y\n001,2026-08-01,90\n001,2026-09-01,100\n");
  await writeFile(join(input, "appendix", "forecast_long.csv"), "unique_id,ds,model,yhat\n001,2026-10-01,Conservative,100\n001,2026-11-01,Conservative,120\n001,2026-10-01,Growth,200\n001,2026-11-01,Growth,300\n001,2026-10-01,Partial,250\n");
  const { runtime, contract } = await configuration();
  service = createService({ workspace, python: runtime.python, contract });
  await service.call("initialize");
  run = await service.call("import_run", { path: input, name: "Synthetic judgment fixture" });
  const catalog = await service.call("catalog");
  await service.call("save_state", { expectedRevision: catalog.revision, state: {
    documents: [{ id: "judgment", runId: run.id, title: "Synthetic model · judgment worksheet", series: "001", view: "Adjust" }],
    activeId: "judgment", theme: "light",
  } });
  server = await startServer({ workspace, service });
});
test.afterAll(async () => { await server?.close(); await service?.close(); });

test("choose models, judge precisely, import, persist branches and compare saved adjusted outputs", async ({ page }) => {
  test.setTimeout(600000);
  page.setDefaultTimeout(120000);
  const errors = [], jobs = [];
  page.on("pageerror", error => errors.push(error.message));
  page.on("request", request => { if (request.url().endsWith("/api") && request.postDataJSON()?.operation === "start_job") jobs.push(request.postDataJSON()); });
  await page.goto(server.url);
  const panel = page.getByRole("region", { name: "Forecast adjustment worksheet", exact: true });
  const grid = panel.getByRole("region", { name: "Editable adjustment grid", exact: true });
  const save = panel.getByRole("button", { name: "Save new judgment version", exact: true });
  const first = grid.locator("tbody tr").first().locator("td").nth(4);
  await expect(first).toHaveText("100.00");
  await panel.getByLabel("Adjustment model", { exact: true }).selectOption("Growth");
  await expect(first).toHaveText("200.00");
  await expect(panel.getByLabel("Adjustment model", { exact: true }).locator('option[value="Partial"]')).toHaveAttribute("disabled", "");
  await panel.getByLabel("Bulk change (%)", { exact: true }).fill("-10");
  await expect(first).toHaveText("180.00");
  await expect(grid.locator("tfoot")).toContainText("450.00");
  await panel.getByLabel("Absolute change per period (minutes)", { exact: true }).fill("-5");
  await expect(first).toHaveText("175.00");
  await expect(grid.locator("tfoot")).toContainText("440.00");
  await panel.getByLabel("Apply through", { exact: true }).selectOption("2026-10-01");
  await expect(grid.locator("tfoot")).toContainText("475.00");
  await panel.getByLabel("2026-11-01 percent", { exact: true }).fill("-20");
  await panel.getByLabel("2026-11-01 amount", { exact: true }).fill("-10");
  await expect(grid.locator("tfoot")).toContainText("405.00");
  await panel.getByLabel("2026-10-01 override", { exact: true }).fill("0");
  await expect(first).toHaveText("0.00");
  await expect(grid.locator("tfoot")).toContainText("230.00");
  await panel.getByRole("button", { name: "Clear adjustments", exact: true }).click();
  await panel.getByLabel("Bulk change (%)", { exact: true }).fill("-10");
  await panel.getByLabel("Adjustment version name", { exact: true }).fill("Leadership");
  await panel.getByLabel("Adjustment rationale", { exact: true }).fill("Capacity risk, explicit 10% judgment.");
  await panel.getByLabel("Bulk change (%)", { exact: true }).fill("-");
  await expect(save).toBeDisabled();
  await expect(panel.getByRole("alert")).toContainText("finite number");
  await panel.getByLabel("Bulk change (%)", { exact: true }).fill("-10");
  await panel.getByRole("button", { name: "Export worksheet & recipe", exact: true }).click();
  const [csvFile] = await Promise.all([page.waitForEvent("download"), panel.getByRole("button", { name: "Download worksheet CSV", exact: true }).click()]);
  const raw = await readFile(await csvFile.path(), "utf8");
  expect(raw).toContain("adjusted_yhat");
  const [jsonFile] = await Promise.all([page.waitForEvent("download"), panel.getByRole("button", { name: "Download judgment JSON", exact: true }).click()]);
  const recipe = JSON.parse(await readFile(await jsonFile.path(), "utf8"));
  expect(Number(recipe.totals.adjusted_yhat)).toBe(450);
  expect(recipe.settings.model).toBe("Growth");
  await panel.getByText("Upload or paste adjustments from Excel", { exact: true }).click();
  await panel.getByLabel("Upload adjustment CSV", { exact: true }).setInputFiles({ name: "oversized.csv", mimeType: "text/csv", buffer: Buffer.alloc(128 * 1024 + 1, "x") });
  await expect(panel.getByRole("alert")).toContainText("128 KiB");
  await panel.getByLabel("Upload adjustment CSV", { exact: true }).setInputFiles({ name: "adjustments.csv", mimeType: "text/csv", buffer: Buffer.from(raw) });
  await expect(panel.getByLabel("Bulk change (%)", { exact: true })).toHaveValue("0");
  await expect(grid.locator("tfoot")).toContainText("450.00");
  await panel.getByLabel("Paste adjustment cells", { exact: true }).fill("ds\toverride\tnote\n2026-10-01\t220\tLaunch\n2026-11-01\t310\tCapacity");
  await panel.getByRole("button", { name: "Import pasted rows", exact: true }).click();
  await expect(grid.locator("tfoot")).toContainText("530.00");
  await panel.getByLabel("Paste adjustment cells", { exact: true }).fill("ds\toverride\n2026-09-01\t99");
  await panel.getByRole("button", { name: "Import pasted rows", exact: true }).click();
  await expect(panel.getByRole("alert")).toContainText("future horizon");
  await expect(grid.locator("tfoot")).toContainText("530.00");
  await panel.getByRole("button", { name: "Clear adjustments", exact: true }).click();
  await panel.getByLabel("Bulk change (%)", { exact: true }).fill("-10");
  await save.click();
  await expect(panel.getByRole("heading", { name: "Branch from Leadership", exact: true })).toBeVisible();
  await expect(save).toBeDisabled();
  await expect(first).toHaveText("180.00");
  await expect(page.locator(".save-state")).toContainText("Saved");
  const firstCatalog = await service.call("catalog");
  const leadership = firstCatalog.runs.find(item => item.metadata.judgmentLabel === "Leadership");
  expect(leadership).toBeTruthy();
  await page.getByRole("navigation", { name: "Analysis views" }).getByRole("button", { name: "Forecast", exact: true }).click();
  await expect(page.getByRole("region", { name: "Forecast values", exact: true })).toContainText("180.00");
  await expect(page.getByText("Leadership · analyst judgment.", { exact: true })).toBeVisible();
  await page.getByRole("navigation", { name: "Analysis views" }).getByRole("button", { name: "Adjust", exact: true }).click();
  await expect(first).toHaveText("180.00");
  await panel.getByLabel("Bulk change (%)", { exact: true }).fill("-20");
  await expect(first).toHaveText("160.00");
  await expect(panel.getByLabel("Adjustment version name", { exact: true })).toBeEnabled();
  await panel.getByLabel("Adjustment version name", { exact: true }).fill("Downside");
  await save.click();
  await expect(panel.getByRole("heading", { name: "Branch from Downside", exact: true })).toBeVisible();
  await expect(first).toHaveText("160.00");
  await panel.getByLabel("Judgment version", { exact: true }).selectOption(leadership.id);
  await panel.getByRole("button", { name: "Compare with this version", exact: true }).click();
  await expect(page.getByRole("region", { name: "Exact version deltas", exact: true })).toContainText("-20.00");
  await page.getByRole("navigation", { name: "Analysis views" }).getByRole("button", { name: "Adjust", exact: true }).click();
  await expect(first).toHaveText("160.00");
  await expect(page.locator(".save-state")).toContainText("Saved");
  await page.reload();
  await expect(first).toHaveText("160.00");
  await expect(panel.getByLabel("Bulk change (%)", { exact: true })).toHaveValue("-20");
  if (process.env.NIXTLA_E2E_CAPTURE !== "0") {
    await panel.locator(".section-heading").first().evaluate(element => element.scrollIntoView({ block: "start" }));
    await page.screenshot({ path: join(workspace, "judgment-desktop.png") });
    await grid.scrollIntoViewIfNeeded();
    await page.screenshot({ path: join(workspace, "judgment-grid.png") });
    await panel.getByRole("region", { name: "Model vs adjusted forecast", exact: true }).screenshot({ path: join(workspace, "judgment-comparison.png") });
  }
  await page.setViewportSize({ width: 390, height: 844 });
  await page.getByRole("button", { name: "Toggle library", exact: true }).click();
  await page.getByLabel("Appearance").selectOption("dark");
  await expect(grid.locator(".judgment-totals")).toContainText("500.00");
  await expect(grid.locator(".judgment-totals")).toContainText("400.00");
  await expect(grid.locator(".judgment-totals")).toContainText("-100.00");
  if (process.env.NIXTLA_E2E_CAPTURE !== "0") {
    await panel.locator(".section-heading").first().evaluate(element => element.scrollIntoView({ block: "start" }));
    await page.screenshot({ path: join(workspace, "judgment-mobile-controls.png") });
    await grid.scrollIntoViewIfNeeded();
    await page.screenshot({ path: join(workspace, "judgment-mobile-grid.png") });
  }
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  await panel.getByLabel("Adjustment version name", { exact: true }).fill("Unsaved assumptions");
  await panel.getByLabel("Judgment version", { exact: true }).selectOption(leadership.id);
  await panel.getByRole("button", { name: "Open judgment version", exact: true }).click();
  const confirmation = page.getByRole("dialog");
  await expect(confirmation).toContainText("Replace unsaved judgment edits?");
  await confirmation.getByRole("button", { name: "Keep editing", exact: true }).click();
  await expect(panel.getByLabel("Adjustment version name", { exact: true })).toHaveValue("Unsaved assumptions");
  await expect(first).toHaveText("160.00");
  await panel.getByRole("button", { name: "Open judgment version", exact: true }).click();
  await confirmation.getByRole("button", { name: "Discard edits and open version", exact: true }).click();
  await expect(first).toHaveText("180.00");
  expect(errors).toEqual([]); expect(jobs).toEqual([]);
  expect((await service.call("catalog")).jobs).toEqual([]);
  expect((await service.call("view", { runId: run.id })).rows[0].yhat).toBe(100);
  console.log(`Judgment artifacts: ${workspace}`);
});

test("chosen model, calendar layer and final judgment persist as a replayable pipeline", async ({ page }) => {
  test.setTimeout(600000);
  page.setDefaultTimeout(120000);
  const catalog = await service.call("catalog");
  await service.call("save_state", { expectedRevision: catalog.revision, state: {
    documents: [{ id: "calendar-chain", runId: run.id, title: "Synthetic calendar pipeline", series: "001", view: "Adjust" }],
    activeId: "calendar-chain", theme: "light",
  } });
  const errors = [], jobs = [];
  page.on("pageerror", error => errors.push(error.message));
  page.on("request", request => { if (request.url().endsWith("/api") && request.postDataJSON()?.operation === "start_job") jobs.push(request.postDataJSON()); });
  await page.goto(server.url);
  const panel = page.getByRole("region", { name: "Forecast adjustment worksheet", exact: true });
  const layer = page.getByRole("region", { name: "Calendar forecast layer", exact: true });
  const grid = panel.getByRole("region", { name: "Editable adjustment grid", exact: true });
  const save = panel.getByRole("button", { name: "Save new judgment version", exact: true });
  await expect(panel.getByLabel("Adjustment model", { exact: true })).toBeEnabled();
  await panel.getByLabel("Adjustment model", { exact: true }).selectOption("Growth");
  await expect(grid.locator("tfoot")).toContainText("500.00");
  await layer.getByLabel("Apply calendar layer", { exact: true }).check();
  await layer.getByLabel("Layer weekend weight", { exact: true }).fill("0.5");
  await layer.getByText("Monthly holiday losses", { exact: true }).click();
  await layer.getByLabel("Holiday loss 2026-11", { exact: true }).fill("4");
  await expect(page.locator(".save-state")).toContainText("Saved");
  await layer.getByRole("button", { name: "Update calendar layer", exact: true }).click();
  await expect(grid.locator("thead")).toContainText("After calendar");
  await expect(grid.locator("tbody tr").first().locator("td").nth(1)).toHaveText("225.53");
  await expect(grid.locator("tfoot")).toContainText("500.00");
  await panel.getByLabel("Bulk change (%)", { exact: true }).fill("-10");
  await expect(grid.locator("tfoot")).toContainText("450.00");
  await expect(grid.locator("tbody tr").first().locator("td").nth(5)).toHaveText("202.98");
  await panel.getByLabel("2026-11-01 override", { exact: true }).fill("0");
  await expect(grid.locator("tbody tr").nth(1).locator("td").nth(5)).toHaveText("0.00");
  await panel.getByLabel("2026-11-01 override", { exact: true }).fill("");
  await layer.getByLabel("Hold model horizon total", { exact: true }).uncheck();
  await expect(page.locator(".save-state")).toContainText("Saved");
  await layer.getByRole("button", { name: "Update calendar layer", exact: true }).click();
  await expect(grid.locator("tfoot")).toContainText("406.73");
  await layer.getByLabel("Hold model horizon total", { exact: true }).check();
  await expect(page.locator(".save-state")).toContainText("Saved");
  await layer.getByRole("button", { name: "Update calendar layer", exact: true }).click();
  await expect(grid.locator("tfoot")).toContainText("450.00");
  await panel.getByLabel("Adjustment version name", { exact: true }).fill("Layered base");
  await panel.getByLabel("Adjustment rationale", { exact: true }).fill("Synthetic weekend and holiday scenario, followed by 10% haircut.");
  await expect(save).toBeEnabled();
  await layer.getByLabel("Layer weekend weight", { exact: true }).fill("");
  await expect(save).toBeDisabled();
  await expect(layer.getByRole("alert")).toContainText("Correct invalid");
  await layer.getByLabel("Layer weekend weight", { exact: true }).fill("0.5");
  await expect(save).toBeEnabled();
  await panel.getByRole("button", { name: "Export worksheet & recipe", exact: true }).click();
  const [jsonFile] = await Promise.all([page.waitForEvent("download"), panel.getByRole("button", { name: "Download judgment JSON", exact: true }).click()]);
  const receipt = JSON.parse(await readFile(await jsonFile.path(), "utf8"));
  expect(receipt.settings.calendar.referencePeriod).toBe("2026-09-01");
  expect(Number(receipt.totals.calendar_yhat)).toBe(500);
  expect(Number(receipt.totals.adjusted_yhat)).toBe(450);
  if (process.env.NIXTLA_E2E_CAPTURE !== "0") {
    await layer.scrollIntoViewIfNeeded();
    await page.screenshot({ path: join(workspace, "calendar-layer-desktop.png") });
    await grid.scrollIntoViewIfNeeded();
    await page.screenshot({ path: join(workspace, "calendar-layer-grid.png") });
  }
  await save.click();
  await expect(panel.getByRole("heading", { name: "Branch from Layered base", exact: true })).toBeVisible();
  await expect(grid.locator("tfoot")).toContainText("450.00");
  await panel.getByRole("button", { name: "Inspect saved finalization pipeline", exact: true }).click();
  const pipeline = page.getByRole("region", { name: "Saved finalization pipeline", exact: true });
  await expect(pipeline.getByRole("button", { name: "2. Calendar layer", exact: false })).toContainText("model total held");
  await pipeline.getByRole("button", { name: "Replay saved recipe", exact: true }).click();
  await expect(pipeline.getByRole("status")).toContainText("Replay verified");
  await expect(pipeline.getByRole("region", { name: "Finalization stage comparison", exact: true })).toContainText("225.53");
  await expect(page.getByLabel("Maintenance operation", { exact: true })).toHaveValue("actuals");
  await expect(page.getByLabel("Maintenance operation", { exact: true }).locator('option[value="refresh"]')).toHaveCount(0);
  await expect(page.getByRole("button", { name: "Review refresh", exact: true })).toHaveCount(0);
  const outcomes = pipeline.getByRole("region", { name: "Finalization stage comparison", exact: true });
  expect(await outcomes.evaluate(element => {
    const scroll = element.querySelector(".table-scroll").getBoundingClientRect();
    const final = [...element.querySelectorAll("th")].find(node => node.textContent === "Final forecast").getBoundingClientRect();
    return final.left >= scroll.left && final.right <= scroll.right;
  })).toBe(true);
  if (process.env.NIXTLA_E2E_CAPTURE !== "0") {
    await pipeline.locator("h2").evaluate(element => element.scrollIntoView({ block: "start" }));
    await page.screenshot({ path: join(workspace, "calendar-pipeline-desktop.png") });
  }
  await expect(page.locator(".save-state")).toContainText("Saved");
  await page.reload();
  await expect(pipeline).toContainText("Layered base");
  await pipeline.getByRole("button", { name: "Open adjustment worksheet", exact: true }).click();
  await expect(layer.getByLabel("Apply calendar layer", { exact: true })).toBeChecked();
  await expect(layer.getByLabel("Layer weekend weight", { exact: true })).toHaveValue("0.5");
  await expect(grid.locator("tfoot")).toContainText("450.00");
  await expect(panel.getByLabel("Bulk change (%)", { exact: true })).toHaveValue("-10");
  await page.setViewportSize({ width: 390, height: 844 });
  await page.getByRole("button", { name: "Toggle library", exact: true }).click();
  await page.getByLabel("Appearance").selectOption("dark");
  if (process.env.NIXTLA_E2E_CAPTURE !== "0") {
    await layer.locator("h3").evaluate(element => element.scrollIntoView({ block: "start" }));
    await page.screenshot({ path: join(workspace, "calendar-layer-mobile.png") });
  }
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  await layer.getByLabel("Apply calendar layer", { exact: true }).uncheck();
  await expect(grid.locator("thead")).not.toContainText("After calendar");
  await expect(grid.locator("tbody tr").first().locator("td").nth(4)).toHaveText("180.00");
  await layer.getByLabel("Apply calendar layer", { exact: true }).check();
  await layer.getByRole("button", { name: "Update calendar layer", exact: true }).click();
  await expect(grid.locator("tbody tr").first().locator("td").nth(5)).toHaveText("202.98");
  await panel.getByRole("button", { name: "Inspect saved finalization pipeline", exact: true }).click();
  await expect(pipeline).toContainText("Layered base");
  if (process.env.NIXTLA_E2E_CAPTURE !== "0") {
    await pipeline.locator("h2").evaluate(element => element.scrollIntoView({ block: "start" }));
    await page.screenshot({ path: join(workspace, "calendar-pipeline-mobile.png") });
  }
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  expect(await outcomes.locator(".table-scroll").evaluate(element => {
    element.scrollLeft = 600;
    return Math.abs(element.querySelector("tbody .sticky-column").getBoundingClientRect().left - element.getBoundingClientRect().left) <= 2;
  })).toBe(true);
  await page.getByRole("button", { name: "Open original baseline to refresh", exact: true }).click();
  await expect(page.getByLabel("Maintenance operation", { exact: true })).toHaveValue("refresh");
  await expect(pipeline).toHaveCount(0);
  expect(errors).toEqual([]); expect(jobs).toEqual([]);
  expect((await service.call("view", { runId: run.id })).rows[0].yhat).toBe(100);
  console.log(`Calendar pipeline artifacts: ${workspace}`);
});
